def dfs(grid, x, y, memoization_level, value, level):
    if (x, y, value, level) in memoization_level:
        return memoization_level[(x, y, value, level)]

    if grid[x][y] == "#":
        return float("-inf")  # Obstacle

    if grid[x][y] == "S" and "S" not in grid[0:level+1]:
        return value - level  # Starting cell reachable from S

    if x < 0 or y < 0 or x >= len(grid) or y >= len(grid[0]):
        return float("-inf")  # Outside boundary

    steps = count_object_areas(grid, x, y + 1)
    if value[-1] > 0:
        steps += count_object_areas(grid, x, y - 1)

    if steps == 1:
        return min(dfs(grid, x + 1, y, memoization_level, value + v[c-1], level + 1) for c in v if {"S"} <= set(v[k]) for k in range(len(v)))

