def black_white_tiling(n, m, a, b, c):
    tiling = []
    for i in range(min(n, m), 0, -1):
        if i <= b:
            char = '/'
        elif i <= a:
            char = '\\'
        else:
            char = '/.'
        tiling.append((char, char, char, char))
    for _ in range(n):
        tiling.append('//', '--', '/\\', '--')
    for _ in range(m):
        tiling.append('....', '....\n....\n')
    for _ in range(c - min(n, m)):
        if b >= a:
            tiling.append('//', '/\n.\n/')
        if a > b or (a == b and a >= m):
            tiling.append('.,', '....\n....\n')
    return "\n".join("".join(line) for line in tiling)

