def cover_path_distance_estimate(position, path):
    x, y = position
    n, m = len(path), len(path[0])
    result_left = result_right = result_above = result_below = 0

    def cell_in_range(x, y, distance_type):
        global result_above, result_below, result_left, result_right
        if x < 0 or x >= n or y < 0 or y >= m:
            return distance_type == "gap"
        if path[x][y] in "OB":
            return False
        if path[x][y] in ".#":
            result_above = result_below = result_left = result_right = 1
            return True
        result_above, result_below, result_left, result_right = \
            cover_path_distance_estimate((x-1, y-1), path)
        result_above, result_below = 1, result_below+result_above
        return True

    def covers_cell(cell):
        r, c = cell
        path[r+1][c+1], path[r][c+1], path[r-1][c+1], path[r-1][c] = "B", "S", "B", "S"

    cells = set(s for r in range(n) for c in range(m) if path[r][c] == "S")
    for cell in cells:
        covers_cell(cell)
    result_left = result_right = cover_path_distance_estimate(cell, path)

    # Directions to go in.
    dxs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    for dx, dy in dxs:
        x, y = cell
        if not cell_in_range(x, y, "cell"):
            continue
        nv = {pos+(dx, dy) for pos in cells}.union({cover_path_distance_estimate, cell})
        for ncell in nv:
            if ncell in cells:
                cells.remove(ncell)
        if not cells:
            result_left, result_right = closest_point_from_path_distance_estimate(cell, dx, dy, path).left, \
                closest_point_from_path_distance_estimate(cell, dx, dy, path).right

    r, c = cell
    for dx, dy in dxs:
        for _ in range(4):
            x, y = dx+x, dy+y
            if (x, y) == (r, c):
                result_left, result_right = min(1, result_left), min(1, result_right)
            if x < 0 or x >= n or y < 0 or y >= m or path[x][y] in "OB":
                break
    if result_left > result_right:
        result = result_left
    else:
        result = result_right
    return result+1

def closest_point_from_path_distance_estimate(start_point, distance_ahead, distance_back, path):
    cur_pos = (start_point[0]+distance_ahead*distance_back, start_point[1]+distance_back*distance_back)
    best_right, best_left = cur_pos, cur_pos
    step = 1
    while step < abs(distance_back):
        if abs(best_right) == abs(distance_back-(step+1))*step:
            best_right = (best_right[0]+step, best_right[1])
        if not cur_pos[0] < n*2 or not cur_pos[1] < m*2:
            raise ValueError
        if abs(best_left) == abs(distance_back-(step+1))*step:
            best_left = (best_left[0]-step, best_left[1])
        if not cur_pos[0] < n*2 or not cur_pos[1] < m*2:
            raise ValueError
        cur_pos = (cur_pos[0]+distance_back, cur_pos[1]+distance_back)
        step = distance_back+1
    if best_left[0] < n*2 and best_left[0] >= 0 and best_left[1] >= 0 and best_left[1]*abs(distance_back)-best_left[0] < 0:
        better_right = (fileinfo.ans, path) if best_right[0][0] + best_right[0][1] > best_left[0][0] + best_left[0][1] else (fileinfo.ans_a, path_a)
        return better_right
    else:
        return best_left, best_right

