            for coord, char in covered_cells:
                for dx, dy in ((0, 1), (1, 0), (0, -1), (-1, 0)):
                    x, y = coord[0] + dx, coord[1] + dy
                    direction = char
                    if x >= 0 and y >= 0 and x < rows and y < cols and (x, y) not in visited:
                        new_coverage.add((x, y))
                    visited.add((x, y))
            covered_cells = new_coverage.copy()
        return len(covered_cells)

    total_coverage = 0
    for element in black_cells:
        length, character = element
        new_coverage = cover_single_cell({element})
        if new_coverage is None:
