def minimum_bricks(rows, cols, grid):
    black_cells = 0
    min_bricks = float('inf')

    # Count black cells in each column
    for col in grid:
        for i in range(rows):
            for j in range(i, -1, -1):
                if grid[i][cols - (j)] == '#':
                    black_cells += 1
                    break

    # Try to cover white cells using the minimum number of bricks
    for row in range(rows - 1, -1, -1):
        if grid[row].count('.') == 0:
            min_bricks = min(black_cells, min_bricks)
            break
        for i in range(col if col != 0 else 0, 0, -1):
            if grid[row].count('.') == black_cells:
                min_bricks = min(black_cells, min_bricks)
                black_cells = 0
                break
            black_cells -= grid[row].count('.')

    return min_bricks

