from collections import deque

def find_fair_pair(n, m, k, a):
    k -= 1

    left_direction = deque((i, i) for i in range(k + 1, n))
    right_direction = dequeue(direction for direction in deque((m - 1 - i, i) for i in range(m - k + 1, m - 1 + k + 1)) if len(direction) <= max(k, m - k))

    p, q = deque(a[n - k]), deque(a[:k])

    while p and q:
        i, isize, j, jsize = p.popleft()
        if isize > jsize:
            left_direction.popleft()
            if left_direction and i <= left_direction[0][0]:
                if len(p) > 0 and len(q) > 0:
                    i, isize, j, jsize = p.popleft()
                else:
                    if j == jsize - 1:
                        j -= 1
    p, q = deque(a[n - k]), deque(a[:m - k + 1])

    while p and q:
        i, isize, j, isize = q.popleft()
        if isize > jsize:
            right_direction.popleft()
            if right_direction and j + 1 >= right_direction[0][1]:
                if len(q) > 0 and len(p) > 0:
                    j, jsize, i, isize = q.popleft()
                else:
                    if i == isize - 1:
                        i -= 1

    return j           

