def k_closest_to_centroid(points, centroid):
    result = [(float('inf'), 0)] * len(points)
    for i, (x, y) in enumerate(points):
        dx = centroid[0] - x
        dy = centroid[1] - y
        distance = dx * dx + dy * dy
        result[i] = (min(result[i][1], distance), i)
    return [(points[i], distance) for _, i in result]

def find_optimal_center_threshold(n, k, points):
    if k + 1 > n:
        return -1
    if k == n - 1:
        _, idx = k_closest_to_centroid(points, [0, 0])[0]
        return points[idx]
    threshold = sum(line_points[1] - line_points[0] for line_points in points) / 2 / k
    centroid = [0, 0]
    for datum in k_closest_to_centroid(points, centroid):
        if datum[0] < threshold:
            avg_dx = (datum[0] - centroid[0]) / k
            avg_dy = (datum[1] - centroid[1]) / k
            return (avg_dx + centroid[0], avg_dy + centroid[1])
    return centroid[0], centroid[1]

