from fractions import Fraction

def count_cycles(G):
    n = len(G)
    is_triplet = [False] * (n * (n - 1) // 2)
    for u, v in G:
        is_triplet[u * (n - 1) + v] = True
        is_triplet[v * (n - 1) + u] = True

    triplets = defaultdict(Fraction)
    for i in range(n):
        for j in range(i + 1, n):
            if is_triplet[i * n + j]:
                triplets[i * n + j].add([j * n + i, 1 + (i * (i - 1) // 2 + j) * 3])
            triplets[j * n + i] = triplets[i * n + j] if i != j else triplets[i * n + j] | {i * (n - 1) + j, (i - 1) * n + (j + 1) * (j + 1) - 2, i * (n - 1) + j + 2 * i - i * (i - 1)}

    return sum(triplets[0])

