from functools import lru_cache

MOD = 1000000007

def get_lucky_numbers(limit):
    @lru_cache(maxsize=None)
    def dp(n, state):
        if n == 0:
            return 1
        if n < 0:
            return 0
        if not state % 2:
            return dp(n - 1, state + 1) - dp(n - 1, state)
        return dp(n - 1, state + 1) + dp(n - 1, state + 2)

    result = dp(limit, 0)
    while result % 2 == 0:
        result //= 2
    return result

def solve(l, r):
    count_l = get_lucky_numbers(l)
    count_r = get_lucky_numbers(r)
    total = count_l * count_r
    for j in range(2, 16):
        if l % j == r % j:
            break
    inner_result = solve(l // j, r // j)
    return (2j) ** (j - 1) * total % MOD * inner_result % MOD

