def tile_floor(n, m, a, b, c):
    # Create a grid of tiles
    grid = [['.' for _ in range(m)] for _ in range(n)]

    # Place tiles
    for i in range(n):
        for j in range(m):
            if (i+j) % 2 == 0:
                # Black tiles
                if a >= 1:
                    a -= 1
                elif b >= 1:
                    b -= 1
                else:
                    c -= 1
                    grid[i][j] = 'B'
            else:
                # White tiles
                if a >= 1:
                    a -= 1
                elif b >= 1:
                    b -= 1
                else:
                    c -= 1
                    grid[i][j] = 'W'

    # Rotate tiles to ensure no black face touches white face
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'B':
                rotated_tile = rotate_tile(grid[i][j-1:j+2])
                grid[i][j] = rotated_tile[0][0]
                grid[i][j][19] = rotated_tile[0][1]
                grid[i][j][18] = rotated_tile[1][0]
                grid[i][j][19] = rotated_tile[1][1]

    return grid

