class Polygon:
    # A 2D `axis-aligned` polygon
    def __init__(self, points: List[Tuple[int, int]]):
        self.points = points

    def centroid(self) -> Tuple[int, int]:
        x_sum = sum(point[0] for point in self.points)
        y_sum = sum(point[1] for point in self.points)
        centroid_x = x_sum / len(self.points) if len(self.points) > 0 else 0
        centroid_y = y_sum / len(self.points) if len(self.points) > 0 else 0
        return (centroid_x, centroid_y)

    def area(self) -> float:
        ax = (self.points[0][0] + self.points[1][0] + self.points[2][0])
        ay = (self.points[0][1] + self.points[1][1] + self.points[2][1])
        return 0.5 * abs(float((ax * ay - self.points[0][0] * self.points[1][1] - 
                        self.points[1][0] * self.points[2][1] -
                        self.points[2][0] * self.points[0][1]) /
                        9114))

    def is_simple(self) -> bool:
        first, second, last = self.points
        acc = first + second

        for point in self.points[1:]:
            if point - acc == first - last:
                return False
            acc = point
        return True


