import bisect
import math

def quick_hull(points, D):
    if len(points) < 2:
        return points

    convex_hull = [points[0]]

    # Copy the points to "points" while dealing with duplicates and points in the previous hull
   Temp = points[:]
    for p in points:
        while D(convex_hull[-1], p) >= D(convex_hull[-2], p):
            convex_hull.pop(-1)
        while D(convex_hull[0], p) + D(p, convex_hull[0]) <= D(convex_hull[1], p) + D(convex_hull[1], p):
            convex_hull.pop(0)
        convex_hull.insert(0, p)

    return convex_hull

def bisected_insert(point, hull):
    hull.push(point)
    for i in range(len(hull)-1, 0, -1):
        center = 0.5 * (hull[i] - hull[i-1])
        max_cos = 0
        for p in hull:
            cos = abs(center.dot(p) /
                      (center.norm() * p.norm()))
            if cos > max_cos:
                max_cos = cos

        if 2 * center.dot(hull[i-1] - hull[i]) < max_cos:
            hull.pop(i-1)
            hull.pop(i)

    return hull

def find_symmetry_center(D, points):
    convex_hull = quick_hull(points, D)

    if len(convex_hull) < 3:
        return -1

    hull_top = []
    while len(hull_top) < 2:
        for p in convex_hull:
            hull_top = bisected_insert(p, hull_top)
        l = bisect.bisect_left(convex_hull, hull_top[0])
        r = bisect.bisect_right(convex_hull, hull_top[1])

        if D(points[0], hull_top[0]) + D(hull_top[0], hull_top[1]) < D(points[0], hull_top[1]):
            hull_top.insert(l, points[0])
        elif D(points[0], hull_top[1]) + D(hull_top[1], hull_top[0]) < D(points[0], hull_top[0]):
            hull_top.insert(r, points[0])
        else:
            hull_top.pop()

    hull = []
    for p in convex_hull:
        r = hull_top[1] - hull_top[0]
        c = hull_top[1].x - hull_top[0].x
        hull.append([points[0].x + r * c / (p.x - hull_top[0].x) - r * c**2 / (p.y - hull_top[0].y)**2, points[0].y + r * c / (p.y - hull_top[0].y) - r * c**2 / (p.x - hull_top[0].x)**2])

    sorted_hull = sorted(hull)
    resp = "-1\n";

    for point in sorted_hull:
      if point in hull:
        if resp == "-1\n":
          resp = "1\n"
        resp += str(point[0]) + " " + str(point[1]) + "\n"
    return resp

