def calculate_ways(n, m, roads):
    # Create an adjacency list to store connections between junctions
    connections = defaultdict(list)
    for a, b in roads:
        connections[a].append(b)
        connections[b].append(a)

    # Function to perform DFS and calculate cycles
    def dfs(node, path):
        path.append(node)
        if len(path) == 5 and len(connections[node]) != 2:  # Cycle detected
            cycle = []
            node_in_cycle = None
            while node_in_cycle != node:
                node_in_cycle = path[-1]
                cycle.append(node_in_cycle)
                path.pop()
            if cycle not in cycle_counts:
                cycle_counts[cycle] = 1
            else:
                cycle_counts[cycle] += 1
            return
        for neighbor in connections[node]:
            if neighbor not in path:
                dfs(neighbor, path)
        path.pop()

    cycle_counts = {}
    total_cycles = 0
    for i in range(1, n + 1):
        if len(connections[i]) != 2:
            dfs(i, [])
